template:
fn prefix<'a>(
    s: ⟦t1⟧,
    _t: ⟦t2⟧,
) -> &'a str {
    &s[..2]
}

fn main() {
    let text = String::from("rust");
    let mut tag = String::from("v1");
    let p = prefix(&text, &tag);
    tag.clear();
    println!("{p}");
}

tests:
#[test]
fn borrows_first_only() {
    let text = String::from("rust");
    let mut tag = String::from("v1");
    let p = prefix(&text, &tag);
    tag.clear();
    assert_eq!(p, "ru");
}
